typedef unsigned int nlUint32;
typedef unsigned int nslSoundId;
typedef unsigned int nslSourceId;
typedef unsigned int nslEmitterId;
#define NULL 0
#define GAS_COMMAND_LIST_SIZE (12 * 64)
#define GAS_MAX_INSTANCES 48
#define GAS_INSTANCE_ID_MASK 0x00FF
#define GAS_INVALID_ID -1
#define GAS_RPC_COMMAND_LIST 0x100f
#define NSL_NUM_SOUNDS 256
#define NSL_GLOBAL_EMITTER_ID 0
#define NSL_SLOT_MASK 0x000003FF
#define NSL_GET_SLOT_FROM_ID(x) (x&NSL_SLOT_MASK)
#define SIF_RPCM_NOWAIT 1
typedef struct { char string_arg[48]; int int_arg[4]; } GasRpcArgs;
typedef struct {
  unsigned char is_valid:1;
  unsigned char is_ready:1;
  unsigned char is_playing:1;
  unsigned char unused_bits:5;
} GasStatusEntry;
typedef struct {
  int rpc_retval1;
  int rpc_retval2;
  GasStatusEntry instances[GAS_MAX_INSTANCES];
} GasStatus;
template<class T> class fifo_queue {
  T *queue;
  short queue_max, start, end, count;
public:
  short find(const T&, short);
};
struct nslSound {
  bool isReady, used, inRange, isReallyReady;
  bool isPlaying, isReallyPlaying, looping, isQueuing;
  short left, right, old_left, old_right;
  nlUint32 gasInstanceId;
  int pauseCount, dampenCount;
  nslSourceId myId, mySource;
  nslEmitterId myEmitter;
  float rawVolume, positionalVolume, angle, pitch, minDist, maxDist;
};
struct nslEmitter {
  bool used, autoRelease, isALineEmitter;
  nslEmitterId myId;
  float startPosition[3], endPosition[3], position[3];
  fifo_queue<nslSoundId> emittedSounds;
};
struct nslSystem {
  char beforeSounds[0xc040];
  nslSound soundSlots[NSL_NUM_SOUNDS];
  nslEmitter emitterSlots[256];
  nlUint32 sourceSlotsUsedCount, soundSlotsUsedCount;
};
struct sceSifClientData {};
extern "C" char *strncpy(char *, const char *, unsigned int);
extern "C" void *memcpy(void *, const void *, unsigned int);
extern "C" int sceSifCallRpc(sceSifClientData *, int, int, void *, int,
                             void *, int, void *, void *);
void _nslClearSoundSlot(nlUint32, bool);
extern nslSystem nsl;
extern GasStatus g_RPC_status;
extern unsigned char sbuf[GAS_COMMAND_LIST_SIZE], rbuf[GAS_COMMAND_LIST_SIZE];
extern sceSifClientData cd;
__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ g_RPC_status, 0x004A0F98");
__asm__(".equ sbuf, 0x00599580");
__asm__(".equ rbuf, 0x00599880");
__asm__(".equ cd, 0x0059D380");
__asm__(".equ strncpy, 0x003E1FB0");
__asm__(".equ memcpy, 0x003E0C80");
__asm__(".equ sceSifCallRpc, 0x003BB7D0");
__asm__(".equ _nslClearSoundSlot__FUib, 0x00390FC8");
__asm__(".equ find__t10fifo_queue1ZUiRCUis, 0x0038F0A8");

/*** gas_rpc ***/
int nslPs2GasRpc (int command, const char *strarg, int intarg0, int intarg1, int intarg2, int intarg3 )
{
  GasRpcArgs args;
  int arg_size = 0;
  int mode;
  int ret;
static int last_command = 0;

  if (command != GAS_RPC_COMMAND_LIST)
  {
    if (strarg != NULL)
    {
      strncpy(args.string_arg, strarg, 48);
      args.string_arg[47] = '\0'; // cap it, just in case
    }
    else
      args.string_arg[0] = '\0';
    args.int_arg[0] = intarg0;
    args.int_arg[1] = intarg1;
    args.int_arg[2] = intarg2;
    args.int_arg[3] = intarg3;
    arg_size = sizeof(GasRpcArgs);
    memcpy(sbuf, (unsigned int *)(&args), sizeof(args));

    // blocking call to the iop
    mode = 0;
    ret = sceSifCallRpc (&cd, command, mode, (void *) sbuf, arg_size,
      (void *) rbuf, sizeof(GasStatus), NULL, NULL);
  }
  else
  {
    // send up a command list (blocking)
    arg_size = GAS_COMMAND_LIST_SIZE;
    memcpy(sbuf, (unsigned int *)strarg, arg_size);

    mode = 0;
    ret = sceSifCallRpc (&cd, command, mode, (void *) sbuf, arg_size,
      (void *) rbuf, sizeof(GasStatus), NULL, NULL);
  }

  last_command = command;

  if (mode == SIF_RPCM_NOWAIT)
  {
    return ret;
  }
  else
  {
    memcpy(&g_RPC_status, rbuf, sizeof(GasStatus));
    last_command = 0;

    // Run the update
    for (int i=0; i < NSL_NUM_SOUNDS; i++) 
    {
      if (nsl.soundSlots[i].gasInstanceId != (nlUint32)GAS_INVALID_ID) 
      {
        if (g_RPC_status.instances[GAS_INSTANCE_ID_MASK&nsl.soundSlots[i].gasInstanceId].is_valid) 
        {
          nsl.soundSlots[i].isReallyPlaying = g_RPC_status.instances[GAS_INSTANCE_ID_MASK&nsl.soundSlots[i].gasInstanceId].is_playing;
          nsl.soundSlots[i].used = true;
          nsl.soundSlots[i].isReallyReady = g_RPC_status.instances[GAS_INSTANCE_ID_MASK&nsl.soundSlots[i].gasInstanceId].is_ready;
          if (nsl.soundSlots[i].isPlaying)
            nsl.soundSlots[i].isReady = true;
          else 
            nsl.soundSlots[i].isReady = nsl.soundSlots[i].isReallyReady;
        } 
        else 
        {
          // Fix up emitters
          if (nsl.soundSlots[i].myEmitter != NSL_GLOBAL_EMITTER_ID)
            nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(nsl.soundSlots[i].myEmitter)].emittedSounds.find(nsl.soundSlots[i].myId, true);
          _nslClearSoundSlot(i, false);
          nsl.soundSlotsUsedCount--;
        }
      } 

    }

    //printf("retval1 = %d  retval2 = %d\n", g_RPC_status.rpc_retval1, g_RPC_status.rpc_retval2);
    return g_RPC_status.rpc_retval1;
  }
}
